// Verify the Standard Webhooks signature on the raw body before anything else.
// webhook-signature = v1,<base64(HMAC-SHA256(secret, "{webhook-id}.{webhook-timestamp}.{body}"))>
// The secret (whsec_...) is shown once when the webhook is created. Keep it in the FAXFORAGENTS_WEBHOOK_SECRET
// environment variable of n8n and allow it with NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const raw = item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64') : Buffer.from(JSON.stringify(item.json.body));
const secret = $env.FAXFORAGENTS_WEBHOOK_SECRET || '';
const msgId = headers['webhook-id'] || '';
const ts = headers['webhook-timestamp'] || '';
const sigs = headers['webhook-signature'] || '';
const fail = (reason) => [{ json: { ok: false, reason, event_id: msgId } }];
if (!secret) return fail('FAXFORAGENTS_WEBHOOK_SECRET is not set');
if (!msgId || !ts || !sigs) return fail('missing webhook headers');
if (!/^\d+$/.test(ts)) return fail('bad timestamp');
if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) return fail('timestamp outside tolerance');
const key = Buffer.from(secret.replace(/^whsec_/, ''), 'base64');
const expected = 'v1,' + crypto.createHmac('sha256', key).update(`${msgId}.${ts}.`).update(raw).digest('base64');
const match = sigs.split(/\s+/).some((c) => c.length === expected.length && crypto.timingSafeEqual(Buffer.from(c), Buffer.from(expected)));
if (!match) return fail('no matching signature');
const event = JSON.parse(raw.toString('utf8'));
return [{ json: { ok: true, event_id: msgId, type: event.type, fax_job_id: event.fax_job_id, data: event.data, environment: event.environment } }];
